from author_csharp_v2 import *

unit(106,
"Attribute metadata توضیحی روی نوع،عضو،پارامتر یا assembly است؛ AttributeUsage target و تکرار را کنترل می‌کند و attribute جنریک نیز قواعد نوع و نسخه دارد. caller information و CallerArgumentExpression اطلاعات call site را در build وارد می‌کنند. Obsolete هشدار مهاجرت،Conditional حذف فراخوانی مشروط و Experimental diagnostic ویژه می‌دهند؛ هیچ‌کدام کنترل امنیتی عمومی نیستند. Reflection با Type و MemberInfo و BindingFlags ساختار و عضوها را می‌خواند؛ Activator و Invoke می‌توانند اجرا کنند و باید محدود به نوع‌های مورد اعتماد باشند. generic metadata با نمونهٔ بسته تفاوت دارد. Reflection.Emit کد پویا تولید می‌کند و در محیط‌هایی مانند Native AOT محدود است. metadata را با رفتار اجرایی خودکار اشتباه نگیر.",
'Console.WriteLine(typeof(Item).GetProperty(nameof(Item.Name))!.Name);\nclass Item {public string Name {get;set;}="A";}', 'Name',
("نام نوع دریافتی از کاربر را می‌توان بدون محدودیت به Activator داد؟", "خیر؛ allowlist و قرارداد مورد اعتماد لازم است.", "بله؛ reflection خودکار sandbox است.", "بله؛ AttributeUsage مرز امنیتی است.", "خواندن metadata با اجرای نوع دلخواه متفاوت است؛ ورودی خارجی نباید مسیر ساخت یا اجرای دلخواه باز کند."),
groups("خواندن یا اجرا", "این APIها را بر اساس نقش غالب در سناریوی درس دسته‌بندی کن.", ["خواندن metadata", "ساخت یا اجرای عضو"], [["Type.GetProperties","MemberInfo.Name"],["Activator.CreateInstance","MethodInfo.Invoke"]]),
"custom attribute برای نام ستون بساز و metadata مدل مورد اعتماد را بخوان. type name خارجی را قبول نکن؛ BindingFlags و target مجاز را روشن نگه دار.",
'using System.Reflection;\nvar property=typeof(Item).GetProperty(nameof(Item.Name))!;\nConsole.WriteLine(property.GetCustomAttribute<ColumnAttribute>()!.Name);\n[AttributeUsage(AttributeTargets.Property)] sealed class ColumnAttribute(string name):Attribute {public string Name {get;}=name;}\nclass Item {[Column("item_name")] public string Name {get;set;}="A";}',
"item_name چاپ شود. attribute فقط روی property مجاز و جست‌وجو محدود به مدل مشخص باشد؛ اجرای type دلخواه از ورودی وجود نداشته باشد.")

unit(107,
"Roslyn syntax tree شکل نوشتاری و semantic model معنای نوع و نمادها را می‌دهد؛ فقط جست‌وجوی متن برای refactoring معتبر کافی نیست. analyzer diagnostic و code fix تغییر پیشنهادی می‌سازد؛ source generator کد جدید را در build به compilation اضافه می‌کند و فایل ورودی را بازنویسی نمی‌کند. incremental generator مراحل تبدیل داده را برای cache و محاسبهٔ دوبارهٔ محدود مدل می‌کند؛ خروجی باید deterministic و مستقل از ساعت یا شبکه باشد. JSON،Regex و logging نمونه‌های تولید کد زمان build دارند. خطای ورودی باید diagnostic روشن بدهد،نه کد خراب مبهم. generated source باید قابل بازبینی و تست باشد و با reflection زمان اجرا یکی نیست.",
'using System.Text.RegularExpressions;\nConsole.WriteLine(Regex.IsMatch("123","^[0-9]+$"));', 'True',
("source generator معمولی در چه زمانی کد اضافه می‌کند؟", "زمان build در compilation", "حتماً در اولین درخواست HTTP", "بعد از انتشار فقط با reflection", "generator ورودی build را می‌خواند و source به compilation می‌افزاید؛ اجرای runtime برنامه نیست."),
constraints("چرخهٔ تولید کد", "generator باید خروجی معتبر و diagnostic قابل تست بدهد.", ["خواندن syntax و semantic لازم", "اعتبارسنجی قرارداد ورودی", "تولید source deterministic", "افزودن source به compilation", "build و بررسی diagnostic و خروجی"], [[0,1],[1,2],[2,3],[3,4]]),
"در پروژهٔ generator از IIncrementalGenerator استفاده کن و برای یک type مشخص عضو تولیدشده اضافه کن. تست ورودی معتبر و diagnostic ورودی نامعتبر بنویس. نمونهٔ مرجع generator کوچک و deterministic است؛ آن را با GeneratorDriver در تست اجرا کن.",
'using Microsoft.CodeAnalysis;\n[Generator] public sealed class HelloGenerator:IIncrementalGenerator\n{\n    public void Initialize(IncrementalGeneratorInitializationContext context)\n    {\n        context.RegisterPostInitializationOutput(output=>output.AddSource("Hello.g.cs","internal static class GeneratedHello { public const string Text = \\"Hello\\"; }"));\n    }\n}',
"generator با Roslyn SDK به‌صورت کتابخانه build شود؛ تست driver وجود GeneratedHello.Text را بسنجد. برای نسخهٔ وابسته به ورودی،syntax/semantic و diagnostic واقعی افزوده شود؛ زمان یا شبکه در تولید دخالت نکند.")

unit(108,
"بعضی قراردادهای زبان با الگوی عضوها و attributeها به کامپایلر معرفی می‌شوند. custom interpolated string handler می‌تواند ساخت متن را برای sink خاص کنترل کند و از کار بی‌نیاز جلوگیری کند؛ باید هزینهٔ context واقعی سنجیده شود. CollectionBuilder نوع builder و متد ساخت از ReadOnlySpan را برای collection expression معرفی می‌کند. overload resolution به نوع مقصد،تبدیل‌ها و قواعد نسخهٔ زبان وابسته است؛ OverloadResolutionPriority از C#13 می‌تواند انتخاب در API را هدایت کند و نباید ناسازگاری پنهان بسازد. برای اثبات انتخاب overload از خروجی یا diagnostic تست‌شده استفاده کن و در صورت نیاز IL تولیدشده را ببین. قرارداد حداقلی کافی بهتر از مجموعهٔ attributeهای بدون مصرف است.",
'using System.Runtime.CompilerServices;\nvar handler=new DefaultInterpolatedStringHandler(2,1);handler.AppendLiteral("N=");handler.AppendFormatted(3);\nConsole.WriteLine(handler.ToStringAndClear());', 'N=3',
("CollectionBuilder عمدتاً کدام قرارداد را مشخص می‌کند؟", "راه ساخت نوع از عناصر collection expression", "مرز امنیتی برای اجرای دادهٔ کاربر", "تضمین صفر بودن همهٔ تخصیص‌ها", "builder الگوی ساخت زمان کامپایل را به متد معتبر وصل می‌کند؛ هزینه و مالکیت همچنان قرارداد پیاده‌سازی‌اند."),
analogy("attribute و قرارداد compiler", "جفت مرجع: CollectionBuilder به ساخت collection expression. جفت دوم را با رابطهٔ «اعلام قرارداد به مصرف کامپایلر» بساز.", ["اعلام قرارداد به مصرف کامپایلر", "مالکیت حافظه", "InterpolatedStringHandler", "ساخت handler رشتهٔ درون‌یابی‌شده", "GC.Collect", "ساخت namespace"], [[0,2,3]]),
"یک collection کوچک با CollectionBuilder بساز و [1,2] را به آن نسبت بده. خروجی را تست کن و برای دو overload سازگار انتخاب واقعی را با marker بررسی کن.",
'using System.Collections;using System.Runtime.CompilerServices;\nBag values=[1,2];Console.WriteLine(string.Join(",",values));\n[CollectionBuilder(typeof(BagBuilder),nameof(BagBuilder.Create))]\npublic sealed class Bag(int[] values):IEnumerable<int>\n{public IEnumerator<int> GetEnumerator()=>((IEnumerable<int>)values).GetEnumerator();IEnumerator IEnumerable.GetEnumerator()=>GetEnumerator();}\npublic static class BagBuilder {public static Bag Create(ReadOnlySpan<int> values)=>new(values.ToArray());}',
"1,2 چاپ شود؛ builder امضای معتبر داشته باشد و دادهٔ نگهداری‌شده عمر مستقل بسازد. marker overload در تست جدا با همان نسخهٔ زبان بررسی شود.")

unit(109,
"unsafe اجازهٔ pointer و عملیات فاقد بعضی حفاظت‌های مدیریت‌شده را می‌دهد؛ نیاز به تنظیم AllowUnsafeBlocks دارد و سرعت را تضمین نمی‌کند. & آدرس و * dereference است؛ pointer arithmetic بر اندازهٔ نوع اشاره‌شده حرکت می‌کند. fixed محل دادهٔ مدیریت‌شده را در محدودهٔ معتبر pin می‌کند و بعد از خروج نباید pointer نگه داشت. stackalloc buffer کوتاه‌عمر می‌سازد و اندازهٔ نامحدود ورودی خطرناک است. sizeof،fixed-size buffer و nint/nuint یا IntPtr/UIntPtr برای اندازه و آدرس بومی‌اند. function pointer قرارداد calling convention می‌خواهد. Unsafe class بررسی bounds و عمر را به مسئولیت مصرف‌کننده منتقل می‌کند؛ استفادهٔ پیش‌فرض از Span امن‌تر است مگر نیاز اندازه‌گیری‌شده وجود داشته باشد.",
'unsafe {int* data=stackalloc int[2];data[0]=2;data[1]=3;Console.WriteLine(data[0]+data[1]);}', '5',
("pointer به stackalloc بعد از خروج scope چه وضعی دارد؟", "نباید مصرف یا نگهداری شود؛ عمر منبع پایان یافته است.", "همیشه به heap منتقل می‌شود.", "GC عمر آن را خودکار تمدید می‌کند.", "pointer مالکیت یا تمدید عمر ایجاد نمی‌کند؛ bounds و lifetime مسئولیت کد unsafe است."),
repair("مرز pointer", "buffer دقیقاً چهار int دارد؛ شرط حلقهٔ دسترسی را اصلاح کن.", ["i <= 4", "i < 4", "i < 5"], [0], ["چهار عنصر خوانده می‌شوند", "خانهٔ بیرون buffer خوانده نمی‌شود"], [([0],[False,False]),([1],[True,True]),([2],[False,False])]),
"buffer ثابت چهارعضوی را یک بار با Span و یک بار pointer محدود پردازش کن. نتیجه‌ها یکسان باشند؛ unsafe block کوچک و مسئولیت bounds و طول عمر مستند باشد.",
'unsafe\n{\n    const int length=4;int* buffer=stackalloc int[length];int sum=0;\n    for(int i=0;i<length;i++) {buffer[i]=i+1;sum+=buffer[i];}\n    if(sum!=10) throw new Exception("bounds");Console.WriteLine(sum);\n}',
"10 چاپ شود؛ pointer از scope خارج نشود و طول از ورودی نامطمئن گرفته نشود. هیچ ادعای سریع‌تر بودن بدون benchmark مطرح نشود.")

unit(110,
"P/Invoke عضو extern را به API بومی متصل می‌کند؛ DllImport اتصال runtime و LibraryImport تولید stub در build را برای مسیرهای پشتیبانی‌شده می‌دهند. نام کتابخانه و calling convention و encoding به ABI و پلتفرم وابسته‌اند. blittable یعنی نمایش قابل انتقال بدون تبدیل لازم در شرایط مشخص؛ layout و packing نامناسب داده را خراب می‌کنند. delegate callback باید تا پایان استفادهٔ native زنده بماند و function pointer قرارداد متفاوتی دارد. NativeMemory حافظهٔ بومی می‌دهد و باید با allocator متناظر آزاد شود. SafeHandle مالکیت handle را مدیریت می‌کند؛ UnmanagedCallersOnly ورودی مناسب از native با محدودیت‌های خود است. تست نباید API پلتفرم دیگر را بی‌شرط اجرا کند.",
'using System.Runtime.InteropServices;\nConsole.WriteLine(Marshal.SizeOf<Packet>());\n[StructLayout(LayoutKind.Sequential)] struct Packet {public int Value;}', '4',
("حافظهٔ NativeMemory.Alloc معمولاً با چه آزاد می‌شود؟", "NativeMemory.Free با مالکیت روشن", "رهاکردن مرجع و انتظار برای GC تنها", "هر allocator دلخواه و ناسازگار", "allocator و آزادساز باید متناظر باشند؛ GC حافظهٔ بومی خام را صرفاً با از دست رفتن pointer مدیریت نمی‌کند."),
mission("مالکیت native", "منبع بومی گرفته شده و مسیر موفق و خطا باید آزادسازی متناظر داشته باشند.", [("allocation موفق شده است.","ثبت مالک در wrapper مناسب","رهاکردن pointer بدون مالک"),("پردازش خطا داده است.","آزادسازی متناظر در cleanup","اتکا به GC برای pointer خام"),("callback به native داده می‌شود.","حفظ delegate تا پایان استفادهٔ native","اجازهٔ جمع‌آوری پیش از پایان callback")]),
"یک API بومی کوچک متناسب با سیستم‌عامل wrap کن؛ تست روی پلتفرم دیگر صریح skip شود. مالکیت حافظهٔ بومی را با SafeHandle و Dispose تکراری تست کن؛ نمونهٔ مرجع تخصیص محدود را نشان می‌دهد.",
'using System.Runtime.InteropServices;\nunsafe\n{\n    void* memory=NativeMemory.Alloc(4);if(memory == null) throw new OutOfMemoryException();\n    try {Span<byte> bytes=new(memory,4);bytes.Fill(2);Console.WriteLine(bytes[0]+bytes[3]);}\n    finally {NativeMemory.Free(memory);}\n}',
"4 چاپ شود و حافظه در خطا هم آزاد گردد. wrapper نهایی SafeHandle یا مالک معادل داشته باشد؛ ABI و محدودیت پلتفرم مستند شوند.")

unit(111,
"assembly هویت،نسخه و metadata دارد؛ reference زمان build با load زمان اجرا فرق می‌کند. AssemblyLoadContext جداسازی resolve وابستگی و امکان unload برای context collectible می‌دهد،اما sandbox امنیتی نیست. unload با باقی‌ماندن مرجع به نوع،delegate یا object plugin انجام نمی‌شود؛ فقط درخواست Unload پایان فوری را تضمین نمی‌کند. resource و satellite assembly داده و ترجمه را نگه می‌دارند. InternalsVisibleTo دسترسی friend و extern alias رفع تعارض نام reference را ممکن می‌کنند. strong name هویت امضاشده است،نه مرز اعتماد به کد نامطمئن. AppDomain الگوی تاریخی .NET Framework است و با قرارداد .NET جدید یکسان فرض نمی‌شود.",
'using System.Runtime.Loader;\nvar context=new AssemblyLoadContext("sample",isCollectible:true);\nConsole.WriteLine(context.IsCollectible);context.Unload();', 'True',
("AssemblyLoadContext آیا sandbox اجرای plugin نامطمئن است؟", "خیر؛ جداسازی بارگذاری با مرز امنیتی فرق دارد.", "بله؛ هر کد مخرب را خودکار محدود می‌کند.", "بله؛ strong name هم همهٔ دسترسی‌ها را می‌بندد.", "بارگذاری و هویت تضمین امنیت اجرای کد نامطمئن نیستند؛ این دوره چنین ورودی‌ای را اجرا نمی‌کند."),
conflict("ادعای unload", "همان plugin و همان لحظه را در نظر بگیر.", ["یک مرجع قوی به object plugin در host باقی است", "تمام منابع و ارجاع‌های لازم برای unload حذف شده‌اند", "context از نوع collectible است"], [([0,1],[0,1],"باقی‌ماندن مرجع قوی با حذف همهٔ موانع ارجاعی در همان لحظه سازگار نیست.")]),
"کتابخانهٔ عادی و plugin مورد اعتماد را با load context جدا مقایسه کن. همهٔ ارجاع‌ها را از scope بیرون نده و درخواست unload را ثبت کن؛ باقی‌ماندن یک delegate را به‌عنوان مانع تشخیص بده.",
'using System.Runtime.Loader;\nvar context=new AssemblyLoadContext("plugin",isCollectible:true);\nvar assembly=context.LoadFromAssemblyPath(typeof(Marker).Assembly.Location);\nConsole.WriteLine(AssemblyLoadContext.GetLoadContext(assembly)==context);\nassembly=null;context.Unload();\nclass Marker {}',
"True چاپ شود. این نمونه درخواست unload را نشان می‌دهد و جمع‌آوری فوری را ادعا نمی‌کند؛ تست مانع ارجاعی و resolve وابستگی جدا انجام شود.")

unit(112,
"framework-dependent به runtime نصب‌شده نیاز دارد؛ self-contained runtime را همراه می‌برد. RID هدف سیستم‌عامل و معماری را مشخص می‌کند و single-file فقط بسته‌بندی یک‌فایلی است،نه الزاماً AOT. ReadyToRun بخشی از کامپایل پیشاپیش را با runtime مربوط ترکیب می‌کند. trimming کدِ ظاهراً بی‌استفاده را حذف می‌کند و reflection پویا به annotation یا طراحی قابل تحلیل نیاز دارد. Native AOT محدودیت dynamic code،reflection و plugin loading دارد ولی GC می‌تواند باقی بماند. هشدارهای analyzers را با علت حل کن و suppression بی‌دلیل نزن. file-based app directiveها تنظیمات build را نزدیک فایل می‌آورند؛ انتشار همچنان هدف و آزمون واقعی می‌خواهد.",
'Console.WriteLine(System.Runtime.CompilerServices.RuntimeFeature.IsDynamicCodeSupported);', 'True',
("single-file چه چیزی را به‌تنهایی تضمین نمی‌کند؟", "Native AOT بودن یا حذف نیاز به runtime در همهٔ مدل‌ها", "بسته‌بندی خروجی در فایل واحد طبق تنظیمات", "کاهش تعداد فایل‌های قابل توزیع در مسیر پشتیبانی‌شده", "بسته‌بندی،همراه‌بردن runtime،trimming و AOT محورهای جدا هستند."),
groups("مدل انتشار", "کارت‌ها را به انتخاب runtime همراه و انتخاب تولید کد تقسیم کن؛ هر کارت فقط موضوع اصلی ذکرشده را هدف دارد.", ["runtime همراه یا نصب‌شده", "تولید کد"], [["framework-dependent","self-contained"],["JIT","Native AOT"]]),
"برنامهٔ کوچک را framework-dependent و self-contained برای RID مشخص publish کن. در صورت وجود toolchain،Native AOT هم بساز؛ warning trimming را با علت ثبت کن. نمونهٔ مرجع مسیر بدون dynamic code است.",
'using System.Text.Json;using System.Text.Json.Serialization;\nConsole.WriteLine(JsonSerializer.Serialize(new Item(3),SampleContext.Default.Item));\nrecord Item(int Value);\n[JsonSerializable(typeof(Item))] partial class SampleContext:JsonSerializerContext {}',
"خروجی JIT شامل JSON Value=3 باشد. برای AOT باید metadata تولیدشده یا قرارداد سازگار جایگزین و publish واقعی تست شود؛ موفقیت build JIT مدرک AOT نیست.")

unit(113,
"API عمومی ورودی،خروجی،خطا،null و محدودیت منبع را قرارداد می‌کند. تغییر امضا یا رفتار باید با نسخه‌بندی،XML docs و مسیر Obsolete migration روشن شود. serialization ورودی نامطمئن به validation و allowlist نوع نیاز دارد؛ محدودیت طول و تعداد از مصرف بی‌حد جلوگیری می‌کند. Random برای نمونه‌گیری عادی و RandomNumberGenerator برای تصادف امنیتی است؛ رمزنگاری باید از API استاندارد با الگوریتم و مدیریت کلید مناسب استفاده کند،نه طرح دست‌ساز. log و exception نباید secret را نشت دهند. اجرای کد یا ساخت type دلخواه از متن کاربر در این برنامه مجاز نیست. آزمون خراب‌داده و تغییر ناسازگار به اندازهٔ مسیر خوشحال مهم است.",
'using System.Security.Cryptography;\nbyte[] bytes=RandomNumberGenerator.GetBytes(16);Console.WriteLine(bytes.Length);', '16',
("برای token غیرقابل پیش‌بینی کدام خانواده مناسب است؟", "RandomNumberGenerator با قرارداد امنیتی درست", "Random با seed ساعت", "GetHashCode نام کاربر", "تولید امنیتی به منبع تصادف رمزنگارانه نیاز دارد؛ طول و نحوهٔ استفاده هم بخشی از قراردادند."),
counter("هر تصادفی امن نیست", "ادعا: Random با seed ثابت برای token ورود غیرقابل پیش‌بینی است.", ["دو Random با seed یکسان", "RandomNumberGenerator با API استاندارد"], [("دنبالهٔ تکرارپذیر","غیرقابل پیش‌بینی",True,"seed یکسان دنبالهٔ قابل بازتولید می‌دهد و برای token مناسب نیست."),("منبع تصادف رمزنگارانه","قرارداد امنیتی مناسب",False,"این API برای نیاز امنیتی طراحی شده؛ طول و نگهداری همچنان مهم‌اند.")]),
"API خواندن داده با سقف طول و نسخهٔ مشخص طراحی کن. ورودی null،طول زیاد،قالب خراب و version ناشناخته را تست کن. برای نمونهٔ token از RNG استاندارد استفاده و خود token را log نکن.",
'using System.Security.Cryptography;\nstatic string CreateToken(int bytes) {if(bytes<16||bytes>64) throw new ArgumentOutOfRangeException(nameof(bytes));return Convert.ToHexString(RandomNumberGenerator.GetBytes(bytes));}\nstring token=CreateToken(16);if(token.Length!=32) throw new Exception("length");Console.WriteLine(token.Length);',
"32 چاپ شود بدون افشای token. مرز 15 و 65 رد شوند؛ اعتبارسنجی و محدودیت منابع در API اصلی مستقل از UI اجرا شوند.")

unit(114,
"کتابخانهٔ پیشرفته باید قرارداد ساده‌ای به مصرف‌کننده بدهد و پیچیدگی generator،interop یا بهینه‌سازی را در مرز خودش نگه دارد. مسیر JIT با plugin پویا و مسیر AOT قابل تحلیل نیازهای انتشار متفاوت دارند؛ نباید یک خروجی را بدون آزمون مناسب برای هر دو موفق اعلام کرد. API باید خطا،مالکیت buffer و محدودیت پلتفرم را مستند کند. کد تولیدشده هم نیاز به بازبینی و تست دارد. backward compatibility و رفتار ورودی خراب بخشی از تحویل است. انتخاب قابلیت پیشرفته باید نیاز قابل اندازه‌گیری یا قرارداد روشن را حل کند؛ برای پروژهٔ کوچک نبود نیاز به unsafe یا reflection هم تصمیم معتبر است.",
'Console.WriteLine(Parser.TryValue("42",out int n)?n:-1);\nstatic class Parser {public static bool TryValue(string? text,out int value)=>int.TryParse(text,out value);}', '42',
("برای کتابخانهٔ قابل AOT کدام شاهد کافی نیست؟", "فقط اجرای موفق JIT بدون publish AOT", "publish و اجرای واقعی خروجی AOT روی هدف", "بررسی warningها و قرارداد reflection", "سازگاری AOT باید با تحلیل و خروجی هدف سنجیده شود؛ موفقیت یک مدل انتشار به مدل دیگر تعمیم نمی‌یابد."),
constraints("تحویل کتابخانه", "دو مسیر انتشار پس از تست مشترک می‌توانند مستقل انجام شوند؛ تحویل پس از بررسی هر دو است.", ["تست قرارداد کتابخانه", "publish و تست JIT", "publish و تست AOT با metadata سازگار", "ثبت محدودیت پلتفرم", "تحویل خروجی و دستور بازتولید"], [[0,1],[0,2],[1,4],[2,4],[3,4]]),
"کتابخانهٔ parser و مصرف‌کننده تحویل بده. مسیر AOT از metadata تولیدشده استفاده کند و مسیر plugin پویا جدا باشد؛ تست،warningها،خروجی واقعی و محدودیت پلتفرم را ثبت کن.",
'foreach(string? text in new string?[]{null,"42","bad","2147483648"})\n{bool ok=Parser.TryValue(text,out int n);Console.WriteLine(ok?n.ToString():"invalid");}\npublic static class Parser\n{\n    /// <summary>Reads an Int32; missing, malformed and overflowing input returns false.</summary>\n    public static bool TryValue(string? text,out int value)=>int.TryParse(text,out value);\n}',
"invalid،42،invalid،invalid چاپ شود. کتابخانهٔ پایه مستقل از dynamic code باشد؛ metadata تولیدشده و publish واقعی در بخش serialization جدا تحویل شوند.")
